using UnityEngine.EventSystems;
using System;
using System.Collections;
using System.IO;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
[DefaultExecutionOrder(-1000)]public sealed class GridShiftSavesUI:MonoBehaviour {
 public static GridShiftSavesUI Instance{get;private set;}public static bool IsOpen=>Instance!=null&&Instance.overlay!=null&&Instance.overlay.activeSelf;
 GameObject overlay;RectTransform panel,content;TMP_Text title,status;TMP_InputField companyName;string mode;int viewToken;Action afterLogin;bool login;CanvasGroup group;ScrollRect scroll;System.Collections.Generic.List<Texture2D> thumbs=new System.Collections.Generic.List<Texture2D>();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(Instance==null)new GameObject("GridShiftSaves").AddComponent<GridShiftSavesUI>();}
 void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);var canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=940;var scaler=gameObject.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;gameObject.AddComponent<GraphicRaycaster>();var r=GridShiftUI.Rect("SaveOverlay",transform,Vector2.zero);GridShiftUI.Stretch(r,Vector2.zero,Vector2.zero);r.gameObject.AddComponent<Image>().color=new Color(0,0,0,.975f);overlay=r.gameObject;group=r.gameObject.AddComponent<CanvasGroup>();panel=GridShiftUI.Rect("Panel",r,new Vector2(1400,980));GridShiftUITheme.Surface(panel.gameObject.AddComponent<Image>(),"Painel_Menu_Cantos_Amarelos");title=GridShiftUI.Text(panel,"",32,55);title.rectTransform.anchoredPosition=new Vector2(-240,430);title.rectTransform.sizeDelta=new Vector2(840,55);var back=GridShiftUI.Button(panel,"Voltar",Close,48);var backRect=back.GetComponent<RectTransform>();backRect.anchorMin=backRect.anchorMax=Vector2.one;backRect.pivot=Vector2.one;backRect.anchoredPosition=new Vector2(-30,-22);backRect.sizeDelta=new Vector2(190,48);content=GridShiftUI.Scroll(panel,new Vector2(25,90),new Vector2(-25,-110),out scroll);status=GridShiftUI.Text(panel,"",21,65);status.rectTransform.anchoredPosition=new Vector2(0,-440);status.rectTransform.sizeDelta=new Vector2(1260,65);overlay.SetActive(false);}
 public void EnsureLogin(Action action){if(GridShiftProfiles.LoggedIn){action();return;}afterLogin=action;OpenBase("PERFIL LOCAL");login=true;Clear();var logo=GridShiftUITheme.Art(content,"GS_Simbolo_Transparente",new Vector2(130,130),Vector2.zero);var email=GridShiftUI.Input(content,"E-mail");var password=GridShiftUI.Input(content,"Senha",true);GridShiftUI.Button(content,"Entrar",()=>{string pass=password.text;password.text="";if(!GridShiftProfiles.Login(email.text,pass,out var error)){status.text=error;return;}var next=afterLogin;afterLogin=null;Close();next?.Invoke();},55,true);}
 public void Open(string target){EnsureLogin(()=>{mode=target;login=false;OpenBase(target=="new"?"NOVO JOGO":target=="save"?"SALVAR JOGO":"CARREGAR JOGO");Render();});}
 void OpenBase(string heading){viewToken++;group.interactable=true;overlay.SetActive(true);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;title.text=heading;status.text="";StartCoroutine(Fade());}
 IEnumerator Fade(){group.alpha=0;for(float t=0;t<.16f;t+=Time.unscaledDeltaTime){group.alpha=t/.16f;panel.localScale=Vector3.one*Mathf.Lerp(.98f,1,t/.16f);yield return null;}group.alpha=1;panel.localScale=Vector3.one;}
 void Clear(){foreach(var tex in thumbs)Destroy(tex);thumbs.Clear();foreach(Transform child in content){child.gameObject.SetActive(false);Destroy(child.gameObject);}}
 void Render(){Clear();if(mode=="new"){companyName=GridShiftUI.Input(content,"Nome da empresa");companyName.characterLimit=64;companyName.text=GridShiftProfiles.CompanyName;}for(int i=1;i<=5;i++){int slot=i;bool valid=GridShiftProfiles.Read(i,out var data,out var recovered);bool exists=File.Exists(GridShiftProfiles.SlotPath(slot))||File.Exists(GridShiftProfiles.SlotPath(slot)+".bak");var card=GridShiftUI.Card(content,"SLOT "+slot.ToString("00")+" — "+(valid?data.companyName:exists?"ARQUIVO INVÁLIDO":"VAZIO"),valid?285:165);
 if(valid){var played=TimeSpan.FromSeconds(data.playSeconds);string date=DateTime.TryParse(data.savedUtc,null,System.Globalization.DateTimeStyles.RoundtripKind,out var utc)?utc.ToLocalTime().ToString("dd/MM/yyyy HH:mm"):"Partida anterior";GridShiftUI.Text(card,"Ato "+(data.company?.act??1)+" · R$ "+data.money.ToString("N2")+" · Reputação "+(data.company?.reputation??25)+" · "+(int)played.TotalHours+"h "+played.Minutes+"min",23,40);GridShiftUI.Text(card,"Último save: "+date+(recovered?" · Backup válido disponível":""),21,32);if(mode=="load"){GridShiftUI.Button(card,"Continuar partida",()=>Load(slot),50,true);GridShiftUI.Button(card,"Excluir partida",()=>Confirm("Excluir definitivamente o Slot "+slot+"?",()=>{if(GridShiftProfiles.Delete(slot,true,out var error)){Render();status.text="Partida excluída.";}else status.text=error;}));}else GridShiftUI.Button(card,mode=="new"?"Iniciar nova empresa neste slot":"Salvar neste slot",()=>Choose(slot,exists),50,true);
 string path=GridShiftProfiles.SlotPath(slot)+".png";if(File.Exists(path)){try{var texture=new Texture2D(2,2);if(texture.LoadImage(File.ReadAllBytes(path))){thumbs.Add(texture);var image=GridShiftUI.Rect("Miniatura",card,new Vector2(130,75));image.gameObject.AddComponent<LayoutElement>().ignoreLayout=true;image.anchorMin=image.anchorMax=new Vector2(1,1);image.pivot=Vector2.one;image.anchoredPosition=new Vector2(-24,-25);image.gameObject.AddComponent<RawImage>().texture=texture;image.GetComponent<RawImage>().raycastTarget=false;}else Destroy(texture);}catch{}}
 }else if(mode=="new"||mode=="save")GridShiftUI.Button(card,exists?"Substituir arquivo inválido":"Criar partida",()=>Choose(slot,exists),50,true);else{GridShiftUI.Text(card,exists?"Não é possível carregar. Os demais slots foram preservados.":"Crie uma nova empresa neste espaço.",22,50);if(exists)GridShiftUI.Button(card,"Excluir arquivo inválido",()=>Confirm("Excluir somente este slot inválido?",()=>{GridShiftProfiles.Delete(slot,true,out _);Render();}));}}
 if(mode=="load"&&File.Exists(Path.Combine(Application.persistentDataPath,"gridshift-session.json")))GridShiftUI.Button(content,"Importar partida anterior para um slot vazio",()=>{for(int slot=1;slot<=5;slot++)if(!File.Exists(GridShiftProfiles.SlotPath(slot))){if(GridShiftProfiles.ImportLegacy(slot,out var error)){Render();status.text="Partida anterior importada sem alterar o arquivo original.";}else status.text=error;return;}status.text="Não há slots vazios.";});}
 void Confirm(string message,Action action){string name=companyName!=null?companyName.text:GridShiftProfiles.CompanyName;Clear();GridShiftUI.Text(content,message,30,110);GridShiftUI.Button(content,"Confirmar",()=>action(),55,true);GridShiftUI.Button(content,"Cancelar",Render);pendingName=name;}
 string pendingName;
 void Choose(int slot,bool occupied){string name=companyName!=null?companyName.text:GridShiftProfiles.CompanyName;if(occupied){pendingName=name;Confirm("Substituir a partida do Slot "+slot+"? Os outros slots serão preservados.",()=>Perform(slot,pendingName,true));}else StartCoroutine(SelectAnimation(slot,()=>Perform(slot,name,false)));}
 void Perform(int slot,string name,bool confirmed){if(mode=="new"){if(!GridShiftProfiles.Create(slot,name,confirmed,out var error)){status.text=error;return;}Close();var menu=FindFirstObjectByType<GridShiftMainMenu>();menu?.StartSlot(null,true);}else{GridShiftProfiles.Activate(slot,GridShiftProfiles.CompanyName);bool ok=DeliveryManager.Instance!=null&&DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Save();if(ok){Close();DeliveryManager.Instance.Notify("Progresso salvo com sucesso.");}else status.text="Não foi possível salvar. Aguarde o fim da transição.";}}
 public void Load(int slot){if(!GridShiftProfiles.Read(slot,out var data,out _)){status.text="Este slot está vazio ou inválido.";return;}StartCoroutine(SelectAnimation(slot,()=>{GridShiftProfiles.Activate(slot,data.companyName);Close();var menu=FindFirstObjectByType<GridShiftMainMenu>();if(menu!=null)menu.StartSlot(data,false);}));}
 IEnumerator SelectAnimation(int slot,Action action){int token=viewToken;RectTransform card=null;foreach(Transform child in content)if(child.name.StartsWith("SLOT "+slot.ToString("00")))card=child as RectTransform;if(card==null){action();yield break;}group.interactable=false;GridShiftUITheme.Surface(card.GetComponent<Image>(),"Etiqueta_Selecionada");for(float t=0;t<.15f;t+=Time.unscaledDeltaTime){if(card!=null)card.localScale=Vector3.one*(1+.012f*Mathf.Sin(t/.15f*Mathf.PI));yield return null;}group.interactable=true;if(token==viewToken&&overlay.activeSelf)action();}
 public void Continue(){EnsureLogin(()=>{if(GridShiftProfiles.Latest(out int slot,out var data)){GridShiftProfiles.Activate(slot,data.companyName);Close();FindFirstObjectByType<GridShiftMainMenu>()?.StartSlot(data,false);}else Open("load");});}
 public void Close(){viewToken++;Clear();overlay.SetActive(false);login=false;FindFirstObjectByType<GridShiftMainMenu>()?.RefreshContinue();GridShiftControls.SuppressFrame();}
 void Update(){var events=EventSystem.current;bool editing=events!=null&&events.currentSelectedGameObject!=null&&events.currentSelectedGameObject.GetComponentInParent<TMP_InputField>()!=null;if(IsOpen&&GridShiftControls.InterfaceBack(editing)){EscapeInput.Consume();Close();}}
 void OnDestroy(){Clear();if(Instance==this)Instance=null;}
}





